function SqlValueList([string[]]$Values) { (($Values | ForEach-Object { "'" + ($_ -replace "'", "''") + "'" }) -join ',') }
function SqlRows4([string[]]$Rows) { (($Rows | ForEach-Object { $p = $_ -split '\|', 4; "('{0}','{1}','{2}','{3}')" -f ($p[0] -replace "'", "''"),($p[1] -replace "'", "''"),($p[2] -replace "'", "''"),($p[3] -replace "'", "''") }) -join ',') }
function Resolve-File([string]$Path, [string]$Label) { if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw "$Label not found: $Path" }; (Resolve-Path -LiteralPath $Path).Path }
function Assert-TargetDatabaseName([string]$Name) { if ($Name -ne $Database) { throw "REV868C3 read-only verifier is restricted to $Database. Actual: $Name" }; if ($RejectedDatabases -contains $Name -or $Name -match '(?i)rev861') { throw "Protected database rejected: $Name" } }
function Get-MigrationEvidenceSql { $mv = (($ExpectedMigrations | ForEach-Object { "('$_')" }) -join ','); @"
with expected("MigrationId") as (values $mv), actual as (select "MigrationId" from "public"."__EFMigrationsHistory"), summary as (select (select count(*) from expected) expected_count,(select count(*) from actual where "MigrationId" in (select "MigrationId" from expected)) actual_matched_count,(select count(*) from expected e left join actual a on a."MigrationId"=e."MigrationId" where a."MigrationId" is null) missing_count,(select count(*) from actual a left join expected e on e."MigrationId"=a."MigrationId" where e."MigrationId" is null) unexpected_count,(select count(*) from (select "MigrationId" from actual group by "MigrationId" having count(*)>1) d) duplicate_count)
select 'migration_expected_count='||expected_count from summary union all select 'migration_actual_matched_count='||actual_matched_count from summary union all select 'migration_missing_count='||missing_count from summary union all select 'migration_unexpected_count='||unexpected_count from summary union all select 'migration_duplicate_count='||duplicate_count from summary union all select 'migration_acceptance_state='||case when expected_count=10 and actual_matched_count=10 and missing_count=0 and unexpected_count=0 and duplicate_count=0 then 'PASS' else 'FAIL' end from summary;
"@ }
