with expected(code) as (select unnest(array[$relieved])), actual(code) as (select "EmployeeCode" from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status") in ('left / resigned','left/resigned','resigned','inactive')) select 'relieved_employee_expected_count='||(select count(*) from expected) union all select 'relieved_employee_actual_matched_count='||(select count(*) from actual a join expected e using(code)) union all select 'relieved_employee_missing_count='||(select count(*) from expected e left join actual a using(code) where a.code is null) union all select 'relieved_employee_unexpected_count='||(select count(*) from actual a left join expected e using(code) where e.code is null);
select 'employee_code_duplicate_count='||count(*) from (select "EmployeeCode" from nexa.employees group by "EmployeeCode" having count(*)>1) d;
select 'payroll_id_duplicate_count='||count(*) from (select "PayrollEmployeeId" from nexa.employees where "PayrollEmployeeId" is not null group by "PayrollEmployeeId" having count(*)>1) d;
select 'narren_doj_acceptance_count='||count(*) from nexa.employees where "EmployeeCode"='SESS-040' and "DateOfJoining"=date '2026-02-01' and "IsDateOfJoiningApproximate"=false;
select 'mageshwari_identity_acceptance_count='||count(*) from nexa.employees where "EmployeeCode"='SESS-049' and "PayrollEmployeeId"='1072' and "Gender"='Female';
select 'login_enabled_mismatch_count='||count(*) from nexa.employees e join nexa.rev868c3_employee_backup b on b."EmployeeId"=e."Id" where e."LoginEnabled" is distinct from b."LoginEnabled";
select 'approval_status_mismatch_count='||count(*) from nexa.employees e join nexa.rev868c3_employee_backup b on b."EmployeeId"=e."Id" where e."ApprovalStatus" is distinct from b."ApprovalStatus";
select 'active_employee_acceptance_state='||case when (select count(*) from (select unnest(array[$active]) code) e left join (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status")='active') a using(code) where a.code is null)=0 and (select count(*) from (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status")='active') a left join (select unnest(array[$active]) code) e using(code) where e.code is null)=0 then 'PASS' else 'FAIL' end;
select 'relieved_employee_acceptance_state='||case when (select count(*) from (select unnest(array[$relieved]) code) e left join (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status") in ('left / resigned','left/resigned','resigned','inactive')) a using(code) where a.code is null)=0 and (select count(*) from (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status") in ('left / resigned','left/resigned','resigned','inactive')) a left join (select unnest(array[$relieved]) code) e using(code) where e.code is null)=0 then 'PASS' else 'FAIL' end;
select 'employee_acceptance_state='||case when (select count(*) from (select unnest(array[$active]) code) e left join (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status")='active') a using(code) where a.code is null)=0 and (select count(*) from (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status")='active') a left join (select unnest(array[$active]) code) e using(code) where e.code is null)=0 and (select count(*) from (select unnest(array[$relieved]) code) e left join (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status") in ('left / resigned','left/resigned','resigned','inactive')) a using(code) where a.code is null)=0 and (select count(*) from (select "EmployeeCode" code from nexa.employees where "EmployeeCode" like 'SESS-%' and lower("Status") in ('left / resigned','left/resigned','resigned','inactive')) a left join (select unnest(array[$relieved]) code) e using(code) where e.code is null)=0 and (select count(*) from (select "EmployeeCode" from nexa.employees group by "EmployeeCode" having count(*)>1) d)=0 and (select count(*) from (select "PayrollEmployeeId" from nexa.employees where "PayrollEmployeeId" is not null group by "PayrollEmployeeId" having count(*)>1) d)=0 and (select count(*) from nexa.employees where "EmployeeCode"='SESS-040' and "DateOfJoining"=date '2026-02-01' and "IsDateOfJoiningApproximate"=false)=1 and (select count(*) from nexa.employees where "EmployeeCode"='SESS-049' and "PayrollEmployeeId"='1072' and "Gender"='Female')=1 then 'PASS' else 'FAIL' end;
