"@ }
function Get-ManagerMappingEvidenceSql { $rows = SqlRows4 $ManagerMappingRows; $dept = SqlValueList $DepartmentCodes; @"
with expected(department_code,scope,primary_code,alternate_code) as (values $rows), actual(department_code,scope,primary_code,alternate_code) as (select d."Code",m."Scope",p."EmployeeCode",coalesce(a."EmployeeCode",'') from nexa.department_approval_mappings m join nexa.departments d on d."Id"=m."DepartmentId" join nexa.employees p on p."Id"=m."PrimaryApproverEmployeeId" left join nexa.employees a on a."Id"=m."AlternateApproverEmployeeId" where m."ApprovalRouteCode"='MANAGER' and m."IsActive"=true and d."Code" in ($dept)), dupes as (select department_code,scope from actual group by department_code,scope having count(*)>1), invalid_effective as (select m."Id" from nexa.department_approval_mappings m join nexa.departments d on d."Id"=m."DepartmentId" where m."ApprovalRouteCode"='MANAGER' and m."IsActive"=true and d."Code" in ($dept) and (m."EffectiveFrom" is null or (m."EffectiveTo" is not null and m."EffectiveTo"<m."EffectiveFrom")))
select 'manager_mapping_expected_count='||(select count(*) from expected) union all select 'manager_mapping_actual_matched_count='||(select count(*) from actual a join expected e using(department_code,scope,primary_code,alternate_code)) union all select 'manager_mapping_missing_count='||(select count(*) from expected e left join actual a using(department_code,scope,primary_code,alternate_code) where a.department_code is null) union all select 'manager_mapping_unexpected_count='||(select count(*) from actual a left join expected e using(department_code,scope,primary_code,alternate_code) where e.department_code is null) union all select 'manager_mapping_duplicate_count='||(select count(*) from dupes) union all select 'manager_mapping_invalid_effective_count='||(select count(*) from invalid_effective) union all select 'mapping_acceptance_state='||case when (select count(*) from expected e left join actual a using(department_code,scope,primary_code,alternate_code) where a.department_code is null)=0 and (select count(*) from actual a left join expected e using(department_code,scope,primary_code,alternate_code) where e.department_code is null)=0 and (select count(*) from dupes)=0 and (select count(*) from invalid_effective)=0 then 'PASS' else 'FAIL' end union all select 'manager_mapping_acceptance_state='||case when (select count(*) from expected e left join actual a using(department_code,scope,primary_code,alternate_code) where a.department_code is null)=0 and (select count(*) from actual a left join expected e using(department_code,scope,primary_code,alternate_code) where e.department_code is null)=0 and (select count(*) from dupes)=0 and (select count(*) from invalid_effective)=0 then 'PASS' else 'FAIL' end;
"@ }
function Get-WorkflowEvidenceSql { @"
with expected("RouteCode","MinimumAmount","MaximumAmount","StepNumber","ApproverResolutionType","ApproverEmployeeCode","ApproverRoleCode") as (values ('MANAGER_ONLY',0.00::numeric,50000.00::numeric,1,'DEPARTMENT_MAPPING',null::text,'MANAGER'),('MANAGER_MD',50000.01::numeric,500000.00::numeric,1,'DEPARTMENT_MAPPING',null::text,'MANAGER'),('MANAGER_MD',50000.01::numeric,500000.00::numeric,2,'FIXED_EMPLOYEE_ROLE','SESS-002','MANAGING_DIRECTOR'),('MANAGER_MD_TD',500000.01::numeric,null::numeric,1,'DEPARTMENT_MAPPING',null::text,'MANAGER'),('MANAGER_MD_TD',500000.01::numeric,null::numeric,2,'FIXED_EMPLOYEE_ROLE','SESS-002','MANAGING_DIRECTOR'),('MANAGER_MD_TD',500000.01::numeric,null::numeric,3,'FIXED_EMPLOYEE_ROLE','SESS-001','TECHNICAL_DIRECTOR')), actual as (select "RouteCode","MinimumAmount","MaximumAmount","StepNumber","ApproverResolutionType","ApproverEmployeeCode","ApproverRoleCode" from nexa.purchase_approval_workflow_steps where "IsActive"=true), missing as (select * from expected except select * from actual), unexpected as (select * from actual except select * from expected), dupes as (select "RouteCode","StepNumber" from actual group by "RouteCode","StepNumber" having count(*)>1), sequence_bad as (select "RouteCode" from actual group by "RouteCode" having min("StepNumber")<>1 or max("StepNumber")<>count(*)), overlap_bad as (select count(*) c from (select distinct "RouteCode","MinimumAmount","MaximumAmount" from actual) a join (select distinct "RouteCode","MinimumAmount","MaximumAmount" from actual) b on a."RouteCode"<>b."RouteCode" and a."MinimumAmount"<=coalesce(b."MaximumAmount",999999999999.99) and b."MinimumAmount"<=coalesce(a."MaximumAmount",999999999999.99))
select 'workflow_expected_count='||(select count(*) from expected) union all select 'workflow_actual_matched_count='||(select count(*) from actual join expected using("RouteCode","MinimumAmount","MaximumAmount","StepNumber","ApproverResolutionType","ApproverEmployeeCode","ApproverRoleCode")) union all select 'workflow_missing_count='||(select count(*) from missing) union all select 'workflow_unexpected_count='||(select count(*) from unexpected) union all select 'workflow_duplicate_count='||(select count(*) from dupes) union all select 'workflow_sequence_violation_count='||(select count(*) from sequence_bad) union all select 'workflow_overlap_count='||(select c from overlap_bad) union all select 'workflow_acceptance_state='||case when (select count(*) from missing)=0 and (select count(*) from unexpected)=0 and (select count(*) from dupes)=0 and (select count(*) from sequence_bad)=0 and (select c from overlap_bad)=0 then 'PASS' else 'FAIL' end;
"@ }
function Get-PermissionEvidenceSql { $rows = (($ManagerPermissionRows | ForEach-Object { "('" + ($_ -replace "'", "''") + "')" }) -join ','); @"
with expected(row_key) as (values $rows), actual(row_key) as (select p."PageKey"||'|V='||case when rpp."CanView" then 'T' else 'F' end||'|A='||case when rpp."CanApprove" then 'T' else 'F' end||'|R='||case when rpp."CanReject" then 'T' else 'F' end||'|C='||case when rpp."CanRequestClarification" then 'T' else 'F' end||'|RV='||case when rpp."CanRequestRevision" then 'T' else 'F' end||'|AH='||case when rpp."CanViewAuditHistory" then 'T' else 'F' end||'|FC='||case when rpp."HasFullControl" then 'T' else 'F' end from nexa.role_page_permissions rpp join nexa.roles r on r."Id"=rpp."RoleId" join nexa.page_definitions p on p."Id"=rpp."PageDefinitionId" where r."Code"='DEPARTMENT_MANAGER' and p."PageKey" in ('purchase.requisitions','purchase.requisition-approvals')), dupes as (select row_key from actual group by row_key having count(*)>1)
select 'manager_permission_expected_count='||(select count(*) from expected) union all select 'manager_permission_actual_matched_count='||(select count(*) from actual a join expected e using(row_key)) union all select 'manager_permission_missing_count='||(select count(*) from expected e left join actual a using(row_key) where a.row_key is null) union all select 'manager_permission_unexpected_count='||(select count(*) from actual a left join expected e using(row_key) where e.row_key is null) union all select 'manager_permission_duplicate_count='||(select count(*) from dupes) union all select 'manager_permission_acceptance_state='||case when (select count(*) from expected e left join actual a using(row_key) where a.row_key is null)=0 and (select count(*) from actual a left join expected e using(row_key) where e.row_key is null)=0 and (select count(*) from dupes)=0 then 'PASS' else 'FAIL' end union all select 'permission_acceptance_state='||case when (select count(*) from expected e left join actual a using(row_key) where a.row_key is null)=0 and (select count(*) from actual a left join expected e using(row_key) where e.row_key is null)=0 and (select count(*) from dupes)=0 then 'PASS' else 'FAIL' end;
"@ }
