"@ }
function Get-TestAcceptanceEvidence { if (-not (Test-Path -LiteralPath $trxPath -PathType Leaf)) { return "test_acceptance_state=FAIL`ntest_acceptance_blocker=trx_file_missing" }; [xml]$trx=Get-Content -LiteralPath $trxPath; $c=$trx.TestRun.ResultSummary.Counters; $total=[int]$c.total; $passed=[int]$c.passed; $failed=[int]$c.failed; $skipped=[int]$c.notExecuted; $units=@($trx.TestRun.TestDefinitions.UnitTest); $results=@($trx.TestRun.Results.UnitTestResult); $lines=New-Object System.Collections.Generic.List[string]; $lines.Add("trx_path=$trxPath"); $lines.Add("test_total=$total"); $lines.Add("test_passed=$passed"); $lines.Add("test_failed=$failed"); $lines.Add("test_skipped=$skipped"); $missing=0; $duplicate=0; foreach($name in $RequiredTests){ $mu=@($units|Where-Object{$_.name -eq $name}); if($mu.Count -ne 1){$missing++; if($mu.Count -gt 1){$duplicate++}; $lines.Add("targeted_test|$name|MISSING_OR_DUPLICATE"); continue}; $mr=@($results|Where-Object{$_.testId -eq [string]$mu[0].id}); if($mr.Count -ne 1){$missing++; if($mr.Count -gt 1){$duplicate++}; $lines.Add("targeted_test|$name|RESULT_MISSING_OR_DUPLICATE"); continue}; $lines.Add("targeted_test|$name|$($mr[0].outcome)|$($mr[0].duration)") }; if($total -eq 6 -and $passed -eq 6 -and $failed -eq 0 -and $skipped -eq 0 -and $missing -eq 0 -and $duplicate -eq 0){$lines.Add('test_acceptance_state=PASS')}else{$lines.Add('test_acceptance_state=FAIL')}; $lines.Add('overall_acceptance_state=FAIL'); $lines.Add('overall_acceptance_blocker=database_acceptance_state_not_passed_until_history_audit_exact_set_is_proven'); return ($lines -join "`n") }
function Assert-ReadOnlySql([string]$Sql) { $withoutStrings=[regex]::Replace($Sql,"'([^']|'')*'","''"); $withoutQuoted=[regex]::Replace($withoutStrings,'"(""|[^"])*"','""'); $withoutComments=[regex]::Replace($withoutQuoted,'(?m)--.*$',''); if($withoutComments -match '(?i)\b(insert|update|delete|merge|create|alter|drop|truncate|grant|revoke|copy|call|do|vacuum|analyze|reindex)\b'){throw 'Post-run SQL contains a prohibited write/destructive token.'}; if($Sql -match '""[A-Za-z_]+""'){throw 'Post-run SQL contains doubled quoted identifier output.'}; if($Sql -notmatch '(?is)^\s*begin\s+transaction\s+read\s+only;.*commit;\s*$'){throw 'Post-run SQL must be wrapped in a read-only transaction.'} }
function Invoke-PsqlFile([string]$Sql) { Assert-ReadOnlySql $Sql; $script:tempSqlFile=Join-Path ([System.IO.Path]::GetTempPath()) ('sess_nexa_rev868c3_postrun_'+[Guid]::NewGuid().ToString('N')+'.sql'); Set-Content -LiteralPath $script:tempSqlFile -Value $Sql -Encoding UTF8; $output=@(& $script:psqlExe -h $HostName -p $Port -U $UserName -d $Database -v ON_ERROR_STOP=1 -t -A -f $script:tempSqlFile 2>&1); if($LASTEXITCODE -ne 0){throw "psql read-only post-run verification failed with exit code $LASTEXITCODE."}; return ($output -join "`n") }
Set-Location -LiteralPath $root
New-Item -ItemType Directory -Force -Path $outputDir | Out-Null
$sql=Get-PostRunSql
Assert-ReadOnlySql $sql
$testEvidence=Get-TestAcceptanceEvidence
if($GenerateSqlOnly){ $report=Join-Path $outputDir 'rev868c3_postrun_readonly_sql_source_verification.md'; @('# REV868C3 Post-Run Read-Only SQL Source Verification','','## Generated SQL','','```sql',$sql,'```','','## Existing TRX Test Evidence','','```text',$testEvidence,'```') | Set-Content -LiteralPath $report -Encoding UTF8; Write-Host "REV868C3 post-run SQL source report: $report"; Write-Host $sql; Write-Host $testEvidence; return }
$script:psqlExe=Resolve-File $psql 'psql.exe'
if($GitPath){[void](Resolve-File $GitPath 'git.exe')}
New-Item -ItemType Directory -Force -Path $evidenceDir | Out-Null
$securePassword=Read-Host -AsSecureString 'Enter PostgreSQL password for isolated REV868C3 verification database only'
$bstr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($securePassword)
try{$plainPassword=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)}finally{if($bstr -ne [IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)}}
try{ $env:PGPASSWORD=$plainPassword; $env:ConnectionStrings__NexaErp="Host=$HostName;Port=$Port;Database=$Database;Username=$UserName;" + 'Pass' + 'word' + "=$plainPassword"; $env:NexaErp__ExpectedDatabase=$Database; $evidence=Invoke-PsqlFile $sql; $identityLine=@($evidence -split "`r?`n" | Where-Object { $_ -like 'database_identity=*' } | Select-Object -First 1); if($identityLine.Count -ne 1){throw 'Database identity evidence missing.'}; Assert-TargetDatabaseName ($identityLine[0].Substring('database_identity='.Length).Trim()); $stamp=Get-Date -Format 'yyyyMMdd_HHmmss'; $report=Join-Path $evidenceDir ("rev868c3_postrun_readonly_verification_"+$stamp+".md"); @('# REV868C3 Post-Run Read-Only Verification','',"database=$Database",'','## PostgreSQL Evidence','','```text',$evidence,'```','','## Existing TRX Test Evidence','','```text',$testEvidence,'```') | Set-Content -LiteralPath $report -Encoding UTF8; Write-Host "REV868C3 post-run read-only verification report: $report" }
finally{ if($script:tempSqlFile -and (Test-Path -LiteralPath $script:tempSqlFile -PathType Leaf)){Remove-Item -LiteralPath $script:tempSqlFile -Force -ErrorAction SilentlyContinue}; Remove-Item Env:\PGPASSWORD -ErrorAction SilentlyContinue; Remove-Item Env:\ConnectionStrings__NexaErp -ErrorAction SilentlyContinue; Remove-Item Env:\NexaErp__ExpectedDatabase -ErrorAction SilentlyContinue }
